// Validate and normalize input
const raw = $input.first().json;
const body = raw.body || raw;  // n8n webhook 有时包一层
const question = (body.question || '').trim();
const userId = body.user_id || '';
const sessionId = body.session_id || '';
const topK = body.top_k || 5;
const scoreThreshold = body.score_threshold || 0.5;

if (!question) {
  throw new Error('question is required');
}

// Basic text normalization (trim extra spaces, normalize punctuation)
const normalized = question
  .replace(/\s+/g, ' ')
  .replace(/[\u2018\u2019]/g, "'")
  .replace(/[\u201c\u201d]/g, '"');

return {
  original_question: question,
  normalized_question: normalized,
  user_id: userId,
  session_id: sessionId,
  top_k: topK,
  score_threshold: scoreThreshold,
  query_id: Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
};

// Extract query vector and prepare Qdrant search request
const embedResult = $input.first().json;
const queryVector = embedResult.embeddings?.[0] || [];
const meta = $('Validate Input').first().json;

return {
  vector: queryVector,
  limit: meta.top_k,
  score_threshold: meta.score_threshold,
  with_payload: true,
  with_vector: false,
  query_id: meta.query_id,
  user_id: meta.user_id,
  session_id: meta.session_id,
  original_question: meta.original_question,
};

// No relevant results found - return safe fallback response
const meta = $('Build Search Request').first().json;

return {
  answer: '抱歉，未找到相关信息。建议联系班长或组长获取帮助。',
  sources: [],
  confidence: 0,
  found: false,
  query_id: meta.query_id,
  user_id: meta.user_id,
  session_id: meta.session_id,
  original_question: meta.original_question,
};

// Build the RAG prompt with retrieved chunks as reference
const searchResult = $('Qdrant Search').first().json;
const meta = $('Build Search Request').first().json;
const results = searchResult.result || [];

// Format retrieved chunks with metadata
const references = results.map((r, i) => {
  const p = r.payload || {};
  return {
    index: i + 1,
    text: p.chunk_text || '',
    source: p.source_title || '未知来源',
    doc_type: p.doc_type || '',
    category: p.category || '',
    machine_type: p.machine_type || '',
    source_file: p.source_file || '',
    score: r.score || 0,
  };
});

// Build strict prompt
// 取对话历史
const historyNode = $('历史Postgres').first().json;
const rows = historyNode.rows || [];
const historyText = rows.length > 0
  ? '对话历史：\n' + rows.map(r => `问：${r.question}\n答：${r.answer}`).reverse().join('\n') + '\n\n'
  : '';
const systemPrompt =historyText + `你是一个工厂设备知识助手。请严格根据以下参考资料回答问题。

规则：
1. 只能基于提供的参考资料回答，不得编造信息
2. 如果参考资料中没有相关内容，回答"抱歉，未找到相关信息，建议联系班长或组长"
3. 回答要简洁明了，适合一线工人阅读
4. 如涉及安全操作，必须在回答中使用**加粗**提醒
5. 标注信息来源（文档名称）

参考资料：
${references.map(ref => `[${ref.index}] 来源: ${ref.source} (相关性: ${(ref.score * 100).toFixed(0)}%)\n${ref.text}`).join('\n\n')}

用户问题：${meta.original_question}`;

return {
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: meta.original_question }
  ],
  temperature: 0.1,
  max_tokens: 2000,
  references,
  query_id: meta.query_id,
  user_id: meta.user_id,
  session_id: meta.session_id,
  original_question: meta.original_question,
};

// Parse DeepSeek response and format output
const llmResponse = $input.first().json;
const promptData = $('Build RAG Prompt').first().json;
const content = llmResponse.choices?.[0]?.message?.content || llmResponse.message?.content || '';

// Calculate average score of retrieved chunks
const scores = promptData.references.map(r => r.score);
const avgScore = scores.length > 0 ? scores.reduce((a, b) => a + b, 0) / scores.length : 0;

return {
  answer: content,
  sources: promptData.references.map(r => ({
    title: r.source,
    type: r.doc_type,
    score: Math.round(r.score * 100) / 100,
    file_url: r.source_file ? 'http://localhost:8002/files/' + r.source_file : null,
  })),
  confidence: Math.round(avgScore * 100) / 100,
  found: true,
  query_id: promptData.query_id,
  user_id: promptData.user_id,
  session_id: promptData.session_id,
  original_question: promptData.original_question,
};

const data = $input.first().json;
const esc = (s) => (s || '').replace(/'/g, "''");

return {
  sql: `INSERT INTO query_logs (user_id, question, answer, sources, confidence, session_id) VALUES ('${esc(data.user_id)}', '${esc(data.original_question)}', '${esc(data.answer)}', '${esc(JSON.stringify(data.sources))}', ${data.confidence || 0}, '${esc(data.session_id || '')}')`,
  ...data
};

const meta = $('Build Search Request').first().json;
const current = $input.first().json;
return {
  ...current,
  history_sql: "SELECT question, answer FROM query_logs WHERE session_id = '" + meta.session_id + "' AND answer NOT LIKE '%未找到%' ORDER BY created_at DESC LIMIT 5",
};
